     1	/**
     2	 * The Run routes. Thin by design (CODING_STANDARDS, API): parse with zod, call
     3	 * the pipeline or the repository, map the outcome to HTTP. The Run itself runs
     4	 * in the background, so `POST` answers `202` straight away.
     5	 */
     6	import { Router, type Response } from "express";
     7	import { z } from "zod";
     8	import {
     9	  ActiveRunExistsError,
    10	  activeRunResponseSchema,
    11	  createRunResponseSchema,
    12	  errorResponseSchema,
    13	  type Repo,
    14	} from "@auto-apply/shared";
    15	import type { Pipeline } from "../pipeline/pipeline.js";
    16	import { DEMO_UID } from "../user.js";
    17	import { streamRun } from "./run-stream.js";
    18	
    19	/** Run ids are UUIDs; anything else never names a Run (and never a Firestore path). */
    20	const runParamsSchema = z.object({ runId: z.string().regex(/^[A-Za-z0-9-]{1,64}$/) });
    21	
    22	function sendError(res: Response, status: number, code: string, message: string): void {
    23	  res.status(status).json(errorResponseSchema.parse({ error: { code, message } }));
    24	}
    25	
    26	export function runsRouter(repo: Repo, pipeline: Pipeline, heartbeatMs: number): Router {
    27	  const router = Router();
    28	
    29	  router.post("/api/runs", async (_req, res, next) => {
    30	    try {
    31	      const { runId } = await pipeline.startRun(DEMO_UID);
    32	      res.status(202).json(createRunResponseSchema.parse({ runId }));
    33	    } catch (err) {
    34	      if (err instanceof ActiveRunExistsError) {
    35	        sendError(res, 409, "run_active", "A run is already in progress");
    36	        return;
    37	      }
    38	      next(err);
    39	    }
    40	  });
    41	
    42	  router.get("/api/runs/active", async (_req, res, next) => {
    43	    try {
    44	      const run = await repo.getActiveRun(DEMO_UID);
    45	      res.json(activeRunResponseSchema.parse({ run }));
    46	    } catch (err) {
    47	      next(err);
    48	    }
    49	  });
    50	
    51	  router.get("/api/runs/:runId/events", async (req, res, next) => {
    52	    const params = runParamsSchema.safeParse(req.params);
    53	    if (!params.success) {
    54	      sendError(res, 400, "invalid_request", "Malformed run id");
    55	      return;
    56	    }
    57	    try {
    58	      const run = await repo.getRun(params.data.runId);
    59	      if (!run || run.uid !== DEMO_UID) {
    60	        sendError(res, 404, "run_not_found", "No such run");
    61	        return;
    62	      }
    63	      streamRun(req, res, repo, run.runId, heartbeatMs);
    64	    } catch (err) {
    65	      next(err);
    66	    }
    67	  });
    68	
    69	  return router;
    70	}
